<?php
require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; require_login(); $pdo=dogvive_db(); $uid=dogvive_user_id(); $petId=(int)($_GET['mascota']??0);
if(current_role()==='Propietario'){ $q=$pdo->prepare('SELECT id_mascota,Nombre FROM mascota WHERE id_usuario=? ORDER BY Nombre'); $q->execute([$uid]); $pets=$q->fetchAll(); }
else { $q=$pdo->prepare('SELECT DISTINCT m.id_mascota,m.Nombre FROM mascota m JOIN reserva r ON r.id_mascota=m.id_mascota WHERE r.id_entrenador=? ORDER BY m.Nombre'); $q->execute([$uid]); $pets=$q->fetchAll(); }
if(!$petId&&$pets)$petId=(int)$pets[0]['id_mascota']; if($petId&&!in_array($petId,array_map('intval',array_column($pets,'id_mascota'))))$petId=0;
if($_SERVER['REQUEST_METHOD']==='POST'&&current_role()==='Entrenador'){
 try{$petPost=(int)($_POST['id_mascota']??0);$reservation=(int)($_POST['id_reserva']??0);$goal=trim((string)($_POST['objetivo']??''));$progress=(int)($_POST['progreso']??0);$notes=trim((string)($_POST['observaciones']??''));if(!$goal||mb_strlen($goal)>150||$progress<0||$progress>100)throw new RuntimeException('Escribe el objetivo y selecciona un progreso entre 0 y 100 %.');$q=$pdo->prepare('SELECT id_reserva,id_usuario FROM reserva WHERE id_reserva=? AND id_entrenador=? AND id_mascota=?');$q->execute([$reservation,$uid,$petPost]);$reservationData=$q->fetch();if(!$reservationData)throw new RuntimeException('La reserva no está asignada a tu cuenta o no corresponde a esa mascota.');$ins=$pdo->prepare('INSERT INTO entrenamiento (Objetivo,Progreso,Observaciones,Fecha,id_reserva) VALUES (?,?,?,?,?)');$ins->execute([$goal,$progress.'%',$notes,date('Y-m-d'),$reservation]);dogvive_notice($pdo,(int)$reservationData['id_usuario'],'Seguimiento','Se registró una actualización de entrenamiento para tu mascota.','seguimiento.php?mascota='.$petPost);dogvive_flash('success','Informe de entrenamiento guardado.');header('Location: '.base_url().'/seguimiento.php?mascota='.$petPost);exit;}catch(Throwable $e){dogvive_flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar el informe.');header('Location: '.base_url().'/seguimiento.php?mascota='.$petId);exit;}
}
$done=0;$pending=0;$training=[];$reservations=[];$ownerId=0;if($petId){$q=$pdo->prepare("SELECT COUNT(*) FROM reserva WHERE id_mascota=? AND Estado='Completada'");$q->execute([$petId]);$done=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM reserva WHERE id_mascota=? AND Estado IN ('Pendiente','Confirmada')");$q->execute([$petId]);$pending=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT e.*,s.Nombre AS servicio FROM entrenamiento e JOIN reserva r ON r.id_reserva=e.id_reserva LEFT JOIN servicio s ON s.id_servicio=r.id_servicio WHERE r.id_mascota=? AND '.(current_role()==='Entrenador'?'r.id_entrenador=?':'r.id_usuario=?').' ORDER BY e.Fecha DESC');$q->execute([$petId,$uid]);$training=$q->fetchAll();if(current_role()==='Entrenador'){$q=$pdo->prepare('SELECT r.id_reserva,r.id_usuario,s.Nombre AS servicio,r.Fecha FROM reserva r LEFT JOIN servicio s ON s.id_servicio=r.id_servicio WHERE r.id_entrenador=? AND r.id_mascota=? ORDER BY r.Fecha DESC');$q->execute([$uid,$petId]);$reservations=$q->fetchAll();}}
$success=dogvive_flash('success');$error=dogvive_flash('error');start_app('Seguimiento','seguimiento');page_wrap_start('Seguimiento del entrenamiento','Consulta el historial y registra avances de cada sesión.');if($success)echo '<div class="notice">'.e($success).'</div>';if($error)echo '<div class="error-box">'.e($error).'</div>';
if(!$pets){echo '<div class="card"><p>No hay mascotas vinculadas para mostrar el seguimiento.</p>'.(current_role()==='Propietario'?btn('Registrar mascota',page_url('registro-mascota'),'btn-primary'):'').'</div>';}
else { ?><form method="get" class="card" style="margin-bottom:20px"><label>Selecciona una mascota<select name="mascota" onchange="this.form.submit()"><?php foreach($pets as $p): ?><option value="<?= (int)$p['id_mascota'] ?>" <?= $petId===(int)$p['id_mascota']?'selected':'' ?>><?= e($p['Nombre']) ?></option><?php endforeach; ?></select></label><noscript><button class="btn btn-primary" type="submit">Ver seguimiento</button></noscript></form><div class="grid grid-3"><div class="card stat-card"><strong><?= $done ?></strong><small>Sesiones completadas</small></div><div class="card stat-card"><strong><?= $pending ?></strong><small>Sesiones pendientes</small></div><div class="card stat-card"><strong><?= $done+$pending>0?round($done/($done+$pending)*100):0 ?>%</strong><small>Sesiones completadas sobre las registradas</small></div></div>
<?php if(current_role()==='Entrenador'&&$reservations): ?><div class="card" style="margin-top:22px"><h3>Registrar avance de entrenamiento</h3><form method="post"><input type="hidden" name="id_mascota" value="<?= $petId ?>"><label>Reserva / sesión<select name="id_reserva" required><option value="">Selecciona una sesión</option><?php foreach($reservations as $r): ?><option value="<?= (int)$r['id_reserva'] ?>"><?= e('#'.$r['id_reserva'].' · '.$r['servicio'].' · '.$r['Fecha']) ?></option><?php endforeach; ?></select></label><label>Objetivo trabajado<input name="objetivo" maxlength="150" required placeholder="Ej. Responder al llamado"></label><label>Progreso<select name="progreso"><option value="0">0 %</option><?php for($i=10;$i<=100;$i+=10): ?><option value="<?= $i ?>"><?= $i ?> %</option><?php endfor; ?></select></label><label>Observaciones y recomendaciones<textarea name="observaciones" rows="3"></textarea></label><button class="btn btn-primary full" type="submit">Guardar avance</button></form></div><?php endif; ?>
<div class="card" style="margin-top:22px"><h3>Historial de entrenamiento</h3><?php if(!$training): ?><p class="muted">Todavía no hay informes guardados para esta mascota.</p><?php else: foreach($training as $tr): ?><div class="booking-item"><div class="grow"><strong><?= e((string)($tr['Objetivo']??'Entrenamiento')) ?></strong><small class="muted">Sesión: <?= e((string)($tr['servicio']??'Entrenamiento')) ?> · Fecha: <?= e((string)$tr['Fecha']) ?> · Progreso: <?= e((string)$tr['Progreso']) ?></small><p><?= e((string)$tr['Observaciones']) ?></p></div></div><?php endforeach;endif; ?></div><?php }
page_wrap_end();end_app();
